contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, bool doRely) public {
        uint256 before = c.wards(user);

        bool reverted;
        if (doRely) {
            try c.rely(user) { reverted = false; } catch { reverted = true; }
        } else {
            try c.deny(user) { reverted = false; } catch { reverted = true; }
        }

        uint256 afterWard = c.wards(user);

        if (reverted) {
            assert(afterWard == before);
        } else {
            assert(afterWard == (doRely ? 1 : 0));
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, bool doRely) public {
        uint256 before = c.wards(user);

        bool doSucceed = c.wards(address(this)) == 1;

        bool reverted;
        if (doSucceed && doRely) {
            c.rely(user);
            reverted = false;
        } else if (doSucceed && !doRely) {
            c.deny(user);
            reverted = false;
        } else if (doRely) {
            try c.rely(user) { reverted = false; } catch { reverted = true; }
        } else {
            try c.deny(user) { reverted = false; } catch { reverted = true; }
        }

        uint256 afterWard = c.wards(user);

        assert(
            (reverted && afterWard == before) ||
            (!reverted && afterWard == (doRely ? 1 : 0))
        );
    }

    receive() external payable {}
}

