contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, bool doRely) public {
        uint256 before = c.wards(user);
        bool reverted;

        try c.rely(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRely = c.wards(user);

        assert(
            doRely
                ? ((!reverted && afterRely == 1) || (reverted && afterRely == before))
                : afterRely == before
        );

        try c.deny(user) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterDeny = c.wards(user);

        assert(
            !doRely
                ? ((!reverted && afterDeny == 0) || (reverted && afterDeny == afterRely))
                : afterDeny == afterRely
        );

        assert(
            afterRely == before + (doRely && !reverted ? 1 : 0) - (doRely && !reverted && before == 1 ? 0 : 0)
        );
    }

    receive() external payable {}
}

