contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address owner) public payable {
        require(owner != address(0), "zero owner not allowed");
        require(address(this).balance >= 0, "balance ok");
        require(amount <= type(uint128).max, "amount fits uint128");

        uint256 assetsBefore = c.totalAssets();
        uint256 sharesBefore = c.totalSupply();
        uint256 cBalanceBefore = address(c).balance;
        uint256 managerBefore = address(c.investmentManager()).balance;

        bool depositReverted;
        try c.requestDeposit{value: 0}(amount, owner) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 assetsAfter = c.totalAssets();
        uint256 sharesAfter = c.totalSupply();
        uint256 cBalanceAfter = address(c).balance;
        uint256 managerAfter = address(c.investmentManager()).balance;

        bool redeemReverted;
        try c.requestRedeem{value: 0}(amount, owner) {
            redeemReverted = false;
        } catch {
            redeemReverted = true;
        }

        uint256 assetsFinal = c.totalAssets();
        uint256 sharesFinal = c.totalSupply();
        uint256 cBalanceFinal = address(c).balance;

        assert(
            cBalanceFinal == cBalanceBefore
            && (depositReverted || (assetsAfter == assetsBefore && sharesAfter == sharesBefore && managerAfter >= managerBefore))
            && (redeemReverted || (sharesFinal == sharesAfter && assetsFinal == assetsAfter))
        );
    }

    receive() external payable {}
}

