contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user) public payable {
        // Ensure the caller is not a ward by using a user address that is not wards(msg.sender)
        // The test contract is msg.sender, and it is not a ward (fresh deploy, wards only in constructor for deployer).
        require(user != address(this), "test contract is the authorized caller");
        require(c.wards(address(this)) == 0, "test contract unexpectedly has ward status");

        uint256 wardsBefore = c.wards(user);
        address imBefore = address(c.investmentManager());
        uint128 priceBefore = c.latestPrice();
        uint256 lastUpdateBefore = c.lastPriceUpdate();

        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }

        bool fileReverted;
        try c.file("investmentManager", user) { fileReverted = false; } catch { fileReverted = true; }

        bool updatePriceReverted;
        try c.updatePrice(uint128(uint256(1))) { updatePriceReverted = false; } catch { updatePriceReverted = true; }

        bool mintReverted;
        try c.mint(user, 1) { mintReverted = false; } catch { mintReverted = true; }

        bool burnReverted;
        try c.burn(user, 1) { burnReverted = false; } catch { burnReverted = true; }

        assert(
            relyReverted && denyReverted && fileReverted && updatePriceReverted && mintReverted && burnReverted
            && c.wards(user) == wardsBefore
            && address(c.investmentManager()) == imBefore
            && c.latestPrice() == priceBefore
            && c.lastPriceUpdate() == lastUpdateBefore
        );
    }

    receive() external payable {}
}

