contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 what, address data, uint128 price, bool tryFile, bool tryPrice) public payable {
        require(what == "investmentManager" || what != "investmentManager", "always true");

        address beforeManager = address(c.investmentManager());
        uint128 beforePrice = c.latestPrice();

        bool fileReverted = false;
        bool priceReverted = false;
        bool fileTried = false;
        bool priceTried = false;

