            fileTried = true;
            if (what == "investmentManager") {
                c.file("investmentManager", data);
            } else {
                try c.file(what, data) { fileReverted = false; } catch { fileReverted = true; }
            }
        }

        if (tryPrice) {
            priceTried = true;
            try c.updatePrice(price) { priceReverted = false; } catch { priceReverted = true; }
        }

        if (!tryFile) {
            fileReverted = false;
        }
        if (!tryPrice) {
            priceReverted = false;
        }

        if (fileTried && what == "investmentManager") {
            assert(address(c.investmentManager()) == data);
        } else {
            assert(address(c.investmentManager()) == beforeManager);
        }

        if (priceTried) {
            assert(priceReverted || c.latestPrice() == price);
        } else {
            assert(c.latestPrice() == beforePrice);
        }
    }

    receive() external payable {}
}

