        c.file("investmentManager", address(this));

        uint128 beforePrice = c.latestPrice();
        uint256 beforeUpdate = c.lastPriceUpdate();
        uint256 beforeTimestamp = block.timestamp;

        bool isWard = c.wards(caller) == 1;

        bool reverted;
        if (caller == address(this)) {
            try c.updatePrice(newPrice) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool success, ) = address(c).call(
                abi.encodeWithSelector(C.updatePrice.selector, newPrice)
            );
            reverted = !success;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterUpdate = c.lastPriceUpdate();

        if (isWard) {
            assert(!reverted && afterPrice == newPrice && afterUpdate == beforeTimestamp);
        } else {
            assert(reverted && afterPrice == beforePrice && afterUpdate == beforeUpdate);
        }
    }

    receive() external payable {}
}

