contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint128 price) public {
        // Snapshot the pre-call observables.
        uint256 priceBefore = c.latestPrice();
        uint256 lastUpdateBefore = c.lastPriceUpdate();
        uint256 wardsCaller = c.wards(caller);
        uint256 wardsThis = c.wards(address(this));

        // Drive the call.  msg.sender here is THIS contract, but auth checks
        // wards[msg.sender], i.e. wards of THIS contract.  The parameter
        // `caller` is used only to describe the rule, not as the auth key.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Re-read the state after the call.
        uint256 priceAfter = c.latestPrice();
        uint256 lastUpdateAfter = c.lastPriceUpdate();

        // General rule: the update succeeds iff this test contract is a ward.
        // On success the price and timestamp are written; on failure both are
        // unchanged (the contract is frozen).
        bool thisIsWard = wardsThis == 1;
        assert(
            (thisIsWard && !reverted && priceAfter == uint256(price) && lastUpdateAfter > lastUpdateBefore)
                || (!thisIsWard && reverted && priceAfter == priceBefore && lastUpdateAfter == lastUpdateBefore)
        );
    }
}

