contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, bytes32 what, address data, uint128 price) public {
        require(user != address(this));

        uint256 wardsBefore = c.wards(user);
        uint256 senderBefore = c.wards(address(this));

        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }

        bool fileReverted;
        try c.file(what, data) { fileReverted = false; } catch { fileReverted = true; }

        bool mintReverted;
        try c.mint(user, 1) { mintReverted = false; } catch { mintReverted = true; }

        bool burnReverted;
        try c.burn(user, 1) { burnReverted = false; } catch { burnReverted = true; }

        bool updatePriceReverted;
        try c.updatePrice(price) { updatePriceReverted = false; } catch { updatePriceReverted = true; }

        assert(
            relyReverted && denyReverted && fileReverted && mintReverted && burnReverted && updatePriceReverted
                && c.wards(user) == wardsBefore && c.wards(address(this)) == senderBefore
        );
    }
}

