contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address user, uint128 price) public {
        // The test contract deployed c, so c.wards(address(this)) == 1.
        require(c.wards(address(this)) == 1, "test contract should be a ward");

        // rely sets wards[user] = 1.
        c.rely(user);
        uint256 wardsAfter = c.wards(user);

        // deny sets wards[user] = 0.
        c.deny(user);
        uint256 wardsAfterDeny = c.wards(user);

        // updatePrice sets latestPrice and lastPriceUpdate.
        c.updatePrice(price);
        uint128 newPrice = c.latestPrice();
        uint256 newLastUpdate = c.lastPriceUpdate();

        assert(wardsAfter == 1 && wardsAfterDeny == 0 && newPrice == price && newLastUpdate != 0);
    }
}

