contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address owner, uint256 amount, uint256 shares)
        public
        payable
    {
        // The test contract is the owner of c; use a caller that is not this contract
        // When caller == address(this), the withApproval modifier would accept it.
        // Otherwise the call must revert before any state change.
        require(caller != address(this));

        bool revertedDeposit;
        try c.deposit(amount, owner) {
            revertedDeposit = false;
        } catch {
            revertedDeposit = true;
        }

        bool revertedMint;
        try c.mint(shares, owner) {
            revertedMint = false;
        } catch {
            revertedMint = true;
        }

        bool revertedWithdraw;
        try c.withdraw(amount, owner, owner) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        bool revertedRedeem;
        try c.redeem(shares, owner, owner) {
            revertedRedeem = false;
        } catch {
            revertedRedeem = true;
        }

        assert(revertedDeposit && revertedMint && revertedWithdraw && revertedRedeem);
    }

    receive() external payable {}
}

