contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, uint256 value) public payable {
        // The InvMutTest contract is the deployer and therefore an authorized ward.
        uint256 beforeUser = c.wards(user);
        uint256 beforeSelf = c.wards(address(this));

        // The contract itself is a ward, so these calls succeed and mutate wards.
        c.rely(user);
        c.deny(user);

        // After a rely followed by deny from the ward, the user should be back to 0.
        uint256 afterUser = c.wards(user);
        uint256 afterSelf = c.wards(address(this));

        assert(afterUser == 0 && afterSelf == 1 && beforeSelf == 1);
    }

    receive() external payable {}
}

