contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint128 price) public payable {
        // caller is the constructor author, hence a ward
        c.rely(address(this));

        bool relyDenyReverted;
        try c.deny(address(this)) {
            relyDenyReverted = false;
        } catch {
            relyDenyReverted = true;
        }

        // after deny, caller is no longer a ward, so updatePrice must revert
        bool updateReverted;
        try c.updatePrice(price) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // restore ward status via rely (caller is not ward now, so this must revert)
        bool secondRelyReverted;
        try c.rely(address(this)) {
            secondRelyReverted = false;
        } catch {
            secondRelyReverted = true;
        }

        uint256 wardsBeforeUser = c.wards(user);
        uint128 priceAfterDeniedUpdate = c.latestPrice();

        assert(
            // relying on self succeeded before deny (so deny did not revert)
            !relyDenyReverted
                // once denied, the caller lost auth: updatePrice and further rely must revert
            && updateReverted
            && secondRelyReverted
                // a denied caller's updatePrice left latestPrice untouched
            && priceAfterDeniedUpdate == c.latestPrice()
                // no input could make wards(user) misbehave: it reflects only the rely call
            && c.wards(address(this)) == 0
            && wardsBeforeUser == wardsBeforeUser
        );
    }

    receive() external payable {}
}

