contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 what, address data, address caller, uint128 price, address user, uint256 value) public {
        // setup: ensure caller is not a ward if it equals address(this); otherwise all fresh addresses are non-wards.
        // Also ensure caller is not address(this) to avoid auth bypass through constructor-created ward.
        require(caller != address(this));

        address oldAsset = c.asset();
        uint128 oldLatestPrice = c.latestPrice();
        uint256 oldLastPriceUpdate = c.lastPriceUpdate();
        uint256 oldWardBefore = c.wards(user);

        bool revertedFile;
        try c.file(what, data) {
            revertedFile = false;
        } catch {
            revertedFile = true;
        }

        bool revertedRely;
        try c.rely(user) {
            revertedRely = false;
        } catch {
            revertedRely = true;
        }

        bool revertedDeny;
        try c.deny(user) {
            revertedDeny = false;
        } catch {
            revertedDeny = true;
        }

        bool revertedUpdatePrice;
        try c.updatePrice(price) {
            revertedUpdatePrice = false;
        } catch {
            revertedUpdatePrice = true;
        }

        bool revertedMint;
        try c.mint(user, value) {
            revertedMint = false;
        } catch {
            revertedMint = true;
        }

        bool revertedBurn;
        try c.burn(user, value) {
            revertedBurn = false;
        } catch {
            revertedBurn = true;
        }

        // General rule: if the parameter for `file` is not "investmentManager", the file call must revert
        // and must not change the investmentManager address. Also, any caller (including this test contract)
        // that is not a ward must revert on permissioned functions without changing observable state.
        // In our test, this contract is a ward from construction, so the permissioned-call reverts cannot be
        // exercised through msg.sender == this. Instead, we focus on the file param behavior.
        assert(revertedFile == (what != bytes32("investmentManager")));

        // For unrecognized file parameters, and if the file call reverted, then the asset must remain unchanged.
        assert(!revertedFile && what == bytes32("investmentManager") ? c.asset() == oldAsset : c.asset() == oldAsset);

        // Additional general rule: if the file call does not revert, the caller must be a ward. In our setup,
        // the caller is this contract, which is a ward, so this is always true for accepted params. The
        // assertion captures that no state change happens when file reverts.
        assert(revertedFile ? c.latestPrice() == oldLatestPrice : true);
    }

    receive() external payable {}
}

