contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, uint256 seed) public {
        require(user != address(0), "user must be nonzero");
        require(seed != 0, "seed must be nonzero");

        // The test contract deployed c, so it is the initial ward and can rely itself
        // as a setup step, making the test contract an authorized caller.
        c.rely(address(this));

        uint256 beforeWard = c.wards(user);
        bool doRely = (seed % 2 == 0);

        bool reverted;
        if (doRely) {
            try c.rely(user) { reverted = false; } catch { reverted = true; }
        } else {
            try c.deny(user) { reverted = false; } catch { reverted = true; }
        }

        uint256 afterWard = c.wards(user);

        if (!reverted) {
            // Successful authorized call must set the ward flag to exactly 1 (rely) or 0 (deny),
            // regardless of the previous value.
            if (doRely) {
                assert(afterWard == 1);
            } else {
                assert(afterWard == 0);
            }
        } else {
            // A reverted call must not change the stored ward flag.
            assert(afterWard == beforeWard);
        }
    }
}

